Given an array arr[] containing both positive and negative integers, check whether there exists a non-empty subarray whose sum is equal to zero.Examples: Input: arr[] = [4, 2, -3, 1, 6]Output: true Explanation: There is a subarray with zero sum from index 1 to 3 .Sum of subarray [2,-3,1]  is 0 .Input: arr[]=[4, 2, 0, 1, 6]Output: trueExplanation: The third element is zero. A single element is also a sub-array.Input: arr[]=[-3, 2, 3, 1, 6]Output: falseTry It YourselfTable of Content[Naive Approach] Using Nested Loop - O(n^2) Time and O(1) Space[Expected Approach] Using Hashing - O(n) Time and O(n) Space[Naive Approach] Using Nested Loop - O(n^2) Time and O(1) SpaceGenerate every subarray using two nested loops and calculate the sum of each subarray. Check if subarray sum is 0 then return true. Otherwise, if no such subarray found then return false.
            C++

    #include <iostream>
#include <vector>
using namespace std;

bool subArrayExists(vector<int>& arr)
{
    for (int i = 0; i < arr.size(); i++) {

        // starting point of the sub arrray and
        // sum is initialized with first element of subarray
        // a[i]
        int sum = arr[i];
        if (sum == 0)
            return true;

        for (int j = i + 1; j < arr.size(); j++) {

            // we are finding the sum till jth index
            // starting from ith index
            sum += arr[j];
            if (sum == 0)
                return true;
        }
    }
    return false;
}

int main()
{
    vector<int> arr = { -3, 2, 3, 1, 6 };
    if (subArrayExists(arr))
        cout << "true";
    else
        cout << "false";

    return 0;
}


